  return ['[R]', '요약: (한 줄)', `(맡긴 일: ${req.title}${req.n ? ` · ${req.n}개` : ''}${req.shape ? ` · ${req.shape}` : ''} — 이 줄은 지우고 결과를 쓴다)`, ...(head ? [head] : ['(초안 글 · 줄마다)'])].join('\n');
