export const runDays = (r) => (!r ? '' : r.dow.join() === WD.join() ? '평일' : r.dow.length === 7 ? '매일' : `매주 ${r.dow.map((x) => DOW_L[x]).join('·')}`);   // 매주 요일 (2026-10-17 · 주 1~2회 보드)
